-- create_index public.records_chat_conversation:index:records_chat_conversation_customer: on workspace_id, data->>'channel', data->>'connectionid', data->>'externalid', id using btree
CREATE INDEX "records_chat_conversation_customer" ON public."records_chat_conversation" USING btree (workspace_id, (data->>'channel'), ((data->>'connectionId')::uuid), (data->>'externalId'), id);
-- create_index public.records_chat_conversation:index:records_chat_conversation_connection_recent: on workspace_id, data->>'channel', data->>'connectionid', data->>'lastat'desc, iddesc using btree
CREATE INDEX "records_chat_conversation_connection_recent" ON public."records_chat_conversation" USING btree (workspace_id, (data->>'channel'), ((data->>'connectionId')::uuid), (data->>'lastAt') DESC, id DESC);
-- create_index public.records_chat_message:index:records_chat_message_channel_ref: on workspace_id, data->>'channelref', id using btree
CREATE INDEX "records_chat_message_channel_ref" ON public."records_chat_message" USING btree (workspace_id, (data->>'channelRef'), id);
-- create_index public.records_chat_message:index:records_chat_message_reply_of: on workspace_id, data->>'conversationid', data->>'inreplyto', data->>'sentat'desc, iddesc using btree
CREATE INDEX "records_chat_message_reply_of" ON public."records_chat_message" USING btree (workspace_id, ((data->>'conversationId')::uuid), ((data->>'inReplyTo')::uuid), (data->>'sentAt') DESC, id DESC);
-- create_index public.records_chat_message:index:records_chat_message_role_recent: on workspace_id, data->>'role', data->>'sentat'desc, iddesc using btree
CREATE INDEX "records_chat_message_role_recent" ON public."records_chat_message" USING btree (workspace_id, (data->>'role'), (data->>'sentAt') DESC, id DESC);
